s", "county": "Lehigh County"}, "18064": {"low": 325092, "high": 662951, "as_of": "2026-08-31", "city": "Nazareth", "county": "Northampton County"}, "18017": {"low": 300509, "high": 551048, "as_of": "2026-08-31", "city": "Bethlehem", "county": "Northampton County"}, "18055": {"low": 293539, "high": 645683, "as_of": "2026-08-31", "city": "Hellertown", "county": "Northampton County"}, "18013": {"low": 229869, "high": 493634, "as_of": "2026-08-31", "city": "Bangor", "county": "Northampton County"}, "18042": {"low": 214493, "high": 430000, "as_of": "2026-08-31", "city": "Easton", "county": "Northampton County"}, "18102": {"low": 187067, "high": 283121, "as_of": "2026-08-31", "city": "Allentown", "county": "Lehigh County"}}};
